rules.sop:
@Backdrop shape shape=rectangle size=medium color=navy at=400,258
@IntakeZone shape shape=rectangle size=medium color=blue at=200,290
@ReviewZone shape shape=rectangle size=medium color=green at=575,290
@Start shape shape=circle size=large color=blue at=110,245
@Process shape shape=rectangle size=medium color=white label=Validate at=280,245
@Check shape shape=diamond size=medium color=yellow label="ok?" at=480,245
@Done shape shape=circle size=medium color=green at=480,375
@E2EAlpha shape shape=circle size=medium color=red at=80,70
@MainTitle shape shape=text size=large color=navy label="Order flow" at=400,58
@IntakeCaption shape shape=text size=small color=blue label="1 · receive" at=200,152
@ReviewCaption shape shape=text size=small color=green label="2 · review" at=575,152
@e1 edge from=$Start to=$Process style=solid arrow=forward
@e2 edge from=$Process to=$Check style=solid arrow=forward
@e3 edge label=yes from=$Check to=$Done style=dashed arrow=forward
@Intake group members=$IntakeZone,$Start,$Process,$IntakeCaption
@Review group members=$ReviewZone,$Check,$Done,$ReviewCaption

